// GENERATED by scripts/sync-shared.mjs from src/. Edit the source, then run `npm run shared:sync`.
// server-shared: coach safety rules from docs/ARCHITECTURE.md "Coach personas". Enforced in code,
// before and after any AI writing:
//  - never mention body shape, weight or looks; roast the food choice only
//  - never praise skipping meals or going under the user's minimum calorie floor
//  - far below the floor, or three low days in a row → every persona turns gentle
//  - Savage mode only with an explicit 18+ confirmation; attitude, never abuse
import type { PersonaId } from './personas.ts';

export type CoachTrigger = 'meal_saved' | 'daily_digest';
export type DietType = 'veg' | 'egg' | 'nonveg' | 'jain';

export type CoachFacts = {
  trigger: CoachTrigger;
  /** Hour of day in IST, 0–23. */
  hour: number;
  kcal: number;
  protein_g: number;
  meals: number;
  kcal_target: number;
  protein_target: number;
  kcal_floor: number;
  /** Consecutive days before today that ended below the floor (days with at least one log). */
  low_days_before: number;
  diet_type: DietType | null;
};

export type CoachProfile = { persona: PersonaId; savage_mode: boolean; adult_confirmed: boolean };
export type Tone = 'normal' | 'gentle' | 'savage';

/** Late enough that a low total is a real signal, not just "hasn't had dinner yet". */
const EVENING_HOUR = 18;
const FAR_BELOW = 0.6;

export function isLowIntake(f: CoachFacts): boolean {
  if (f.meals === 0) return false; // nothing logged ≠ nothing eaten; never assume
  const dayIsDone = f.trigger === 'daily_digest' || f.hour >= EVENING_HOUR;
  if (!dayIsDone) return false;
  const farBelow = f.kcal < FAR_BELOW * f.kcal_floor;
  const belowAtDayEnd = f.trigger === 'daily_digest' && f.kcal < f.kcal_floor;
  const threeInARow = f.low_days_before >= 2 && f.kcal < f.kcal_floor;
  return farBelow || belowAtDayEnd || threeInARow;
}

export function decideTone(f: CoachFacts, p: CoachProfile): Tone {
  if (isLowIntake(f)) return 'gentle';
  return p.persona === 'gym_bro' && p.savage_mode && p.adult_confirmed ? 'savage' : 'normal';
}

// Body, weight and looks words (English + Hinglish). Matched as whole words.
const BODY_WORDS = [
  'weight',
  'weigh',
  'kg',
  'kilo',
  'kilos',
  'body',
  'bodies',
  'looks',
  'looking',
  'ugly',
  'pretty',
  'handsome',
  'fat',
  'fatty',
  'fatso',
  'chubby',
  'obese',
  'skinny',
  'thin',
  'slim',
  'belly',
  'tummy',
  'waist',
  'thighs',
  'figure',
  'shape',
  'mota',
  'moti',
  'motu',
  'patla',
  'patli',
  'tond',
  'pet',
  'wazan',
  'vajan',
  'sharir',
  'shakal',
];
// Praise for skipping or under-eating.
const SKIP_PATTERNS = [
  /\bskip/i,
  /\bstarv/i,
  /\bfast(ed|ing)\b/i,
  /\bless is more\b/i,
  /\bbhook(a|e)\b/i,
  /\bkhana chhod/i,
];
// Abuse is never allowed, even in Savage mode.
const ABUSE = [
  'chutiya',
  'chutiye',
  'bc',
  'mc',
  'bsdk',
  'gandu',
  'bhosdi',
  'madarchod',
  'behenchod',
  'saala',
  'saali',
  'harami',
  'kamina',
  'idiot',
  'stupid',
  'loser',
];

const wordRe = (words: string[]) => new RegExp(`(^|[^a-z])(${words.join('|')})(?=[^a-z]|$)`, 'i');
const BODY_RE = wordRe(BODY_WORDS);
const ABUSE_RE = wordRe(ABUSE);

export type CheckResult = { ok: true } | { ok: false; reason: string };

/**
 * Checks AI-written (or any) coach text: safety words, length, and that it introduces no numbers
 * beyond the facts we gave it ("no persona can change the facts").
 */
export function checkCoachText(text: string, allowedNumbers: number[]): CheckResult {
  const clean = text.trim();
  if (!clean || clean.length > 280) return { ok: false, reason: 'length' };
  // "fat" is a macro word in our UI copy ("13 g fat"), so allow it only right after a number + g.
  const withoutMacroFat = clean.replace(/\d+\s*g\s+fat\b/gi, '');
  if (BODY_RE.test(withoutMacroFat)) return { ok: false, reason: 'body' };
  if (SKIP_PATTERNS.some((r) => r.test(clean))) return { ok: false, reason: 'skip' };
  if (ABUSE_RE.test(clean)) return { ok: false, reason: 'abuse' };
  const allowed = new Set(allowedNumbers.map((n) => Math.round(n)));
  for (const m of clean.matchAll(/\d[\d,]*(\.\d+)?/g)) {
    const n = Math.round(Number(m[0].replaceAll(',', '')));
    if (n > 3 && !allowed.has(n)) return { ok: false, reason: `number ${n}` };
  }
  return { ok: true };
}
